#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as _dt
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.3.0"

ADVANCED_FILE = base64.b64decode('').decode("utf-8")
TEST_FILE = base64.b64decode('').decode("utf-8")

HIDDEN_IDS = (
    "image.arithmetic.absdiff",
    "image.arithmetic.weighted_blend",
    "image.arithmetic.bitwise_and",
)

REGISTRY_OLD_INIT = '    def __init__(self) -> None:\n        self._definitions: dict[str, OperatorDefinition] = {}\n'
REGISTRY_NEW_INIT = '    def __init__(self) -> None:\n        self._definitions: dict[str, OperatorDefinition] = {}\n        self._catalog_hidden: set[str] = set()\n'
REGISTRY_OLD_MANIFESTS = '    def manifests(self) -> list[dict[str, Any]]:\n        return [definition.to_manifest() for definition in self.list()]\n\n    def clear(self) -> None:\n        self._definitions.clear()\n'
REGISTRY_NEW_MANIFESTS = '    def hide_from_catalog(self, *operator_ids: str) -> None:\n        self._catalog_hidden.update(str(operator_id) for operator_id in operator_ids)\n\n    def show_in_catalog(self, *operator_ids: str) -> None:\n        for operator_id in operator_ids:\n            self._catalog_hidden.discard(str(operator_id))\n\n    def manifests(self) -> list[dict[str, Any]]:\n        return [\n            definition.to_manifest()\n            for definition in self.list()\n            if definition.operator_id not in self._catalog_hidden\n        ]\n\n    def clear(self) -> None:\n        self._definitions.clear()\n        self._catalog_hidden.clear()\n'


def resolve_backend(backend_arg):
    cwd = Path.cwd().resolve()
    candidates = []
    if backend_arg:
        candidates.append(Path(backend_arg).expanduser().resolve())
    candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    backend = next(
        (
            path for path in candidates
            if (path / "app/services/vision_labs/image/operators/__init__.py").exists()
            and (path / "app/services/vision_labs/image/registry.py").exists()
        ),
        None,
    )
    if backend is None:
        raise RuntimeError(
            "Cannot locate Lambda Vision backend. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )
    return backend


def backup(backend, paths):
    stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = backend / ".lambda_updater_backups" / f"image_lab_advanced_raster_v0030_{stamp}"
    root.mkdir(parents=True, exist_ok=True)
    for path in paths:
        if not path.exists():
            continue
        rel = path.relative_to(backend)
        dest = root / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)
    return root


def patch_registry(text):
    if "def hide_from_catalog(" in text:
        return text, False
    if REGISTRY_OLD_INIT not in text or REGISTRY_OLD_MANIFESTS not in text:
        raise RuntimeError(
            "image/registry.py does not match the expected Image LAB registry structure."
        )
    updated = text.replace(REGISTRY_OLD_INIT, REGISTRY_NEW_INIT, 1)
    updated = updated.replace(REGISTRY_OLD_MANIFESTS, REGISTRY_NEW_MANIFESTS, 1)
    return updated, updated != text


def patch_loader(text):
    changed = False

    if "from . import advanced_families" not in text:
        if "    from . import basic_families  # noqa: F401" in text:
            text = text.replace(
                "    from . import basic_families  # noqa: F401",
                "    from . import basic_families  # noqa: F401\n"
                "    from . import advanced_families  # noqa: F401",
                1,
            )
        elif "    from . import builtins  # noqa: F401" in text:
            text = text.replace(
                "    from . import builtins  # noqa: F401",
                "    from . import builtins  # noqa: F401\n"
                "    from . import advanced_families  # noqa: F401",
                1,
            )
        else:
            raise RuntimeError(
                "operators/__init__.py does not match the expected loader structure."
            )
        changed = True

    if "IMAGE_OPERATOR_REGISTRY.hide_from_catalog(" not in text:
        anchor = "    _LOADED = True"
        if anchor not in text:
            raise RuntimeError("Could not locate _LOADED = True in operator loader.")
        hide_lines = [
            "    from app.services.vision_labs.image.registry import IMAGE_OPERATOR_REGISTRY",
            "",
            "    # Image Processing LAB is intentionally single-raster processing only.",
            "    # Legacy/multi-image IDs stay registered for saved-pipeline compatibility.",
            "    IMAGE_OPERATOR_REGISTRY.hide_from_catalog(",
            '        "image.arithmetic.absdiff",',
            '        "image.arithmetic.weighted_blend",',
            '        "image.arithmetic.bitwise_and",',
            "    )",
            "",
        ]
        text = text.replace(anchor, "\n".join(hide_lines) + anchor, 1)
        changed = True

    return text, changed


def scan(backend):
    advanced_path = backend / "app/services/vision_labs/image/operators/advanced_families.py"
    registry_path = backend / "app/services/vision_labs/image/registry.py"
    loader_path = backend / "app/services/vision_labs/image/operators/__init__.py"
    test_path = backend / "tests/vision_labs/image/test_image_lab_advanced_raster.py"

    print("=" * 82)
    print("IMAGE PROCESSING LAB - ADVANCED RASTER PACK V0.3.0")
    print("=" * 82)
    print(f"Backend : {backend}")
    print()

    advanced_ok = advanced_path.exists() and advanced_path.read_text(encoding="utf-8") == ADVANCED_FILE
    registry_text = registry_path.read_text(encoding="utf-8")
    loader_text = loader_path.read_text(encoding="utf-8")
    test_ok = test_path.exists() and test_path.read_text(encoding="utf-8") == TEST_FILE

    print(f"  [{'OK' if advanced_ok else 'WRITE':5}] advanced_families.py")
    print(f"  [{'OK' if 'def hide_from_catalog(' in registry_text else 'PATCH':5}] registry catalog visibility")
    print(f"  [{'OK' if 'from . import advanced_families' in loader_text else 'PATCH':5}] operator loader")
    print(f"  [{'OK' if 'IMAGE_OPERATOR_REGISTRY.hide_from_catalog(' in loader_text else 'PATCH':5}] catalog boundary")
    print(f"  [{'OK' if test_ok else 'WRITE':5}] advanced regression tests")
    print()
    print("Pure-raster families added:")
    for name in (
        "Illumination Correction",
        "Edge-preserving Filter",
        "Ridge / Structure",
        "Distance / Skeleton",
        "Morphological Reconstruction",
        "Advanced Binarization",
        "Frequency Domain",
        "Texture / Local Statistics",
        "Multiscale / Scale-space",
        "Classical Segmentation",
        "Restoration",
    ):
        print(f"  - {name}")
    print()
    print("Hidden from Image LAB catalog but still runtime-compatible:")
    for operator_id in HIDDEN_IDS:
        print(f"  - {operator_id}")
    return 0


def apply(backend):
    advanced_path = backend / "app/services/vision_labs/image/operators/advanced_families.py"
    registry_path = backend / "app/services/vision_labs/image/registry.py"
    loader_path = backend / "app/services/vision_labs/image/operators/__init__.py"
    test_path = backend / "tests/vision_labs/image/test_image_lab_advanced_raster.py"

    backup_root = backup(
        backend,
        [advanced_path, registry_path, loader_path, test_path],
    )

    registry_new, registry_changed = patch_registry(
        registry_path.read_text(encoding="utf-8")
    )
    loader_new, loader_changed = patch_loader(
        loader_path.read_text(encoding="utf-8")
    )

    advanced_path.parent.mkdir(parents=True, exist_ok=True)
    advanced_path.write_text(ADVANCED_FILE, encoding="utf-8")
    print("[WRITE] app/services/vision_labs/image/operators/advanced_families.py")

    if registry_changed:
        registry_path.write_text(registry_new, encoding="utf-8")
        print("[PATCH] app/services/vision_labs/image/registry.py")

    if loader_changed:
        loader_path.write_text(loader_new, encoding="utf-8")
        print("[PATCH] app/services/vision_labs/image/operators/__init__.py")

    test_path.parent.mkdir(parents=True, exist_ok=True)
    test_path.write_text(TEST_FILE, encoding="utf-8")
    print("[WRITE] tests/vision_labs/image/test_image_lab_advanced_raster.py")

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def verify(backend):
    advanced_path = backend / "app/services/vision_labs/image/operators/advanced_families.py"
    registry_path = backend / "app/services/vision_labs/image/registry.py"
    loader_path = backend / "app/services/vision_labs/image/operators/__init__.py"
    test_path = backend / "tests/vision_labs/image/test_image_lab_advanced_raster.py"

    print("=" * 82)
    print("VERIFY IMAGE PROCESSING LAB - ADVANCED RASTER PACK V0.3.0")
    print("=" * 82)

    failures = 0
    registry_text = registry_path.read_text(encoding="utf-8")
    loader_text = loader_path.read_text(encoding="utf-8")
    advanced_text = advanced_path.read_text(encoding="utf-8")

    checks = [
        ("Advanced operator module installed", "class FrangiRidge" in advanced_text and "class WienerDeconvolution" in advanced_text),
        ("Registry supports hidden catalog entries", "def hide_from_catalog(" in registry_text and "_catalog_hidden" in registry_text),
        ("Advanced module loaded", "from . import advanced_families" in loader_text),
        ("Catalog boundary installed", "IMAGE_OPERATOR_REGISTRY.hide_from_catalog(" in loader_text and all(x in loader_text for x in HIDDEN_IDS)),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    for path in (advanced_path, registry_path, loader_path, test_path):
        try:
            py_compile.compile(str(path), doraise=True)
            print(f"[OK] Python syntax {path.name}")
        except Exception as exc:
            print(f"[FAIL] Python syntax {path.name}: {exc}")
            failures += 1

    smoke = r'''
from app.services.vision_labs.image.operators import load_builtin_operators
from app.services.vision_labs.image.registry import IMAGE_OPERATOR_REGISTRY

load_builtin_operators()
all_ids = {definition.operator_id for definition in IMAGE_OPERATOR_REGISTRY.list()}
catalog_ids = {item["id"] for item in IMAGE_OPERATOR_REGISTRY.manifests()}

required = {
    "image.illumination.shading_correction",
    "image.filter.guided",
    "image.structure.frangi_ridge",
    "image.distance.transform",
    "image.skeleton.zhang_suen",
    "image.reconstruction.open",
    "image.threshold.sauvola",
    "image.frequency.filter",
    "image.texture.gabor_bank_max",
    "image.multiscale.dog",
    "image.segment.grabcut_rect",
    "image.restore.wiener",
}
hidden = {
    "image.arithmetic.absdiff",
    "image.arithmetic.weighted_blend",
    "image.arithmetic.bitwise_and",
}

assert required <= all_ids, sorted(required - all_ids)
assert hidden <= all_ids, sorted(hidden - all_ids)
assert hidden.isdisjoint(catalog_ids), sorted(hidden & catalog_ids)
assert len(all_ids) >= 70, len(all_ids)

print("IMAGE_LAB_ALL_OPERATOR_COUNT=", len(all_ids))
print("IMAGE_LAB_CATALOG_OPERATOR_COUNT=", len(catalog_ids))
'''

    proc = subprocess.run(
        [sys.executable, "-c", smoke],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )
    if proc.returncode == 0:
        print("[OK] Registry/catalog smoke")
        print(proc.stdout.strip())
    else:
        print("[FAIL] Registry/catalog smoke")
        print((proc.stdout + "\n" + proc.stderr).strip())
        failures += 1

    pytest_proc = subprocess.run(
        [
            sys.executable,
            "-m",
            "pytest",
            "-q",
            str(test_path.relative_to(backend)),
        ],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )
    if pytest_proc.returncode == 0:
        print("[OK] Advanced raster regression tests")
        print(pytest_proc.stdout.strip())
    else:
        print("[FAIL] Advanced raster regression tests")
        print((pytest_proc.stdout + "\n" + pytest_proc.stderr).strip())
        failures += 1

    if failures:
        print(f"[FAIL] Verification completed with {failures} issue(s).")
        return 1

    print("[OK] Image Processing LAB Advanced Raster Pack v0.3.0 verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--backend")
    args = parser.parse_args()

    try:
        backend = resolve_backend(args.backend)
        if args.command == "scan":
            return scan(backend)
        if args.command == "apply":
            return apply(backend)
        return verify(backend)
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
